// Jumple: Squaredle-style word search where you can jump from any letter to any other.
// Boards come from boards.js, generated by tools/gen.py. Board n is the daily
// Jumple n days after the first one.

// The first daily Jumple, as a local date.
const FIRST_DAY = [2026, 10, 24];
// Share of the board's points needed for each star: red numbers, white numbers, hints.
const STARS = [0.3, 0.55, 0.8];
const MIN_LEN = 4;
const $ = (id) => document.getElementById(id);

const store = {
  get(key) { try { return JSON.parse(localStorage.getItem(key)); } catch { return null; } },
  set(key, value) { try { localStorage.setItem(key, JSON.stringify(value)); } catch {} },
};

let board, boardNo, letters, required, bonusSet, totalPoints, state;
let path = [];        // tile indices of the word being built, in the order tapped

// Longer words score more.
const points = (w) => w.length - 3;

// How many letters the letter hint reveals at the start and end of a word, by length.
function revealed(len) {
  if (len <= 5) return [1, 0];
  if (len === 6) return [2, 0];
  if (len === 7) return [2, 1];
  return [2, 2];
}
function hinted(w) {
  const [head, tail] = revealed(w.length);
  return w.slice(0, head) + '_'.repeat(w.length - head - tail) + (tail ? w.slice(-tail) : '');
}

// ----- days ------------------------------------------------------------------

const dayStart = (y, m, d) => new Date(y, m - 1, d).getTime();
// Today's board number, counting the first daily Jumple as 0. Rounding absorbs daylight saving.
function todayNo() {
  const now = new Date();
  const days = Math.round((dayStart(now.getFullYear(), now.getMonth() + 1, now.getDate()) - dayStart(...FIRST_DAY)) / 864e5);
  return Math.max(0, Math.min(days, BOARDS.length - 1));
}
function dateOf(n) {
  const d = new Date(dayStart(...FIRST_DAY));
  d.setDate(d.getDate() + n);
  return d.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
}
const boardLabel = (n) => `Jumple #${n + 1}`;

// ----- screens ---------------------------------------------------------------

const saved = (n) => {
  const s = store.get('jumple:' + n);
  return s && s.grid === BOARDS[n].grid ? s : null;
};
const isComplete = (n) => saved(n)?.found.length === BOARDS[n].words.length;
function status(n) {
  const s = saved(n), b = BOARDS[n];
  if (!s || !s.found.length) return `${b.words.length} words to find`;
  return s.found.length === b.words.length ? 'Complete ✓' : `${s.found.length} of ${b.words.length} words`;
}

// The home screen: today's board, then every earlier one, newest first.
function showHome() {
  clearInterval(guideTimer);
  $('home').hidden = false; $('game').hidden = true; $('back').hidden = true;
  const today = todayNo();
  $('today').innerHTML = `<span class="kicker">Today's Jumple</span><span class="name">${boardLabel(today)}</span>` +
    `<span class="state">${dateOf(today)} · ${status(today)}</span>`;
  $('today').onclick = () => openBoard(today);
  const list = $('earlier');
  list.innerHTML = '';
  for (let n = today - 1; n >= 0; n--) {
    const li = document.createElement('li');
    li.innerHTML = `<button class="level"><span class="name">${boardLabel(n)}</span>` +
      `<span class="state">${dateOf(n)} · ${status(n)}</span></button>`;
    li.querySelector('button').onclick = () => openBoard(n);
    list.append(li);
  }
  $('earlier-head').hidden = today === 0;
}

function openBoard(n) {
  boardNo = n;
  board = BOARDS[n];
  letters = board.grid;
  required = new Set(board.words);
  bonusSet = new Set(board.bonus);
  totalPoints = board.words.reduce((t, w) => t + points(w), 0);
  state = saved(n) || freshState();
  armed = null;
  path = [];
  $('home').hidden = true; $('game').hidden = false; $('back').hidden = false;
  $('board-name').textContent = `${boardLabel(n)} · ${dateOf(n)}`;
  $('progress').querySelector('.stars').innerHTML =
    STARS.map((s) => `<span class="star" style="left:${s * 100}%">★</span>`).join('');
  buildBoard();
  startGuide();
  render();
  window.scrollTo(0, 0);
}

const save = () => store.set('jumple:' + boardNo, state);
const freshState = () => ({
  grid: letters, order: [...letters].map((_, i) => i), found: [], bonus: [],
  hintLetters: false, hintSort: false, reveals: 1, starReveal: false, revealed: [], guide: null,
});

// ----- board -----------------------------------------------------------------

// Tiles are laid out in state.order, which Shuffle changes; a tile's index
// always refers to its letter in the board's grid.
function buildBoard() {
  const el = $('board');
  el.innerHTML = '';
  for (const i of state.order) {
    const t = document.createElement('div');
    t.className = 'tile';
    t.dataset.i = i;
    t.innerHTML = `<span class="letter">${letters[i]}</span><span class="n start"></span><span class="n use"></span>`;
    el.append(t);
  }
}

const tiles = () => [...$('board').children].sort((a, b) => a.dataset.i - b.dataset.i);

// Tapping a letter adds it to the word; tapping one already in the word takes
// it and everything after it back off.
$('board').addEventListener('click', (e) => {
  const t = e.target.closest('.tile');
  if (!t) return;
  const i = +t.dataset.i;
  const at = path.indexOf(i);
  if (at >= 0) path = path.slice(0, at);
  else path.push(i);
  typedMiss = '';
  renderPath();
});

// ----- typing ----------------------------------------------------------------

// A typed letter that isn't free on the board shows in red until it's deleted.
let typedMiss = '';
document.addEventListener('keydown', (e) => {
  if ($('game').hidden || e.metaKey || e.ctrlKey || e.altKey || document.querySelector('dialog[open]')) return;
  if (e.key === 'Enter') submit();
  else if (e.key === 'Escape') clearPath();
  else if (e.key === 'Backspace') backspace();
  else if (/^[a-z]$/i.test(e.key)) {
    const i = letters.indexOf(e.key.toUpperCase());
    if (typedMiss || i < 0 || path.includes(i)) typedMiss += e.key.toUpperCase();
    else path.push(i);
    renderPath();
  } else return;
  e.preventDefault();
});
function backspace() {
  if (typedMiss) typedMiss = typedMiss.slice(0, -1);
  else path.pop();
  renderPath();
}

// ----- scoring ---------------------------------------------------------------

const wordOnBoard = () => path.map((i) => letters[i]).join('');

function submit() {
  if (typedMiss) { flash(wordOnBoard() + typedMiss, 'Not on the board'); return clearPath(); }
  const w = wordOnBoard();
  if (!w.length) return clearPath();
  if (w.length < MIN_LEN) flash(w, 'Too short');
  else if (state.found.includes(w) || state.bonus.includes(w)) say(`${w}: already found`, 'neutral');
  else if (required.has(w)) {
    clearPath();
    return addFound(w, w === state.guide);
  } else if (bonusSet.has(w)) {
    state.bonus.push(w);
    save();
    toast(`${w}: bonus word`);
  } else flash(w, 'Not in word list');
  clearPath();
  render();
}

// Records a required word as found, whether the player found it or used a reveal on it.
function addFound(w, viaReveal) {
  const before = starsEarned();
  state.found.push(w);
  if (viaReveal) { state.revealed.push(w); state.guide = null; startGuide(); }
  const earned = starsEarned();
  // Reaching the hints star earns one more reveal, once per board.
  let extra = '';
  if (earned >= 3 && !state.starReveal) {
    state.starReveal = true;
    state.reveals++;
    extra = '💡 +1 reveal';
  }
  save();
  const done = state.found.length === board.words.length;
  if (done) toast('🎉 Board complete! Every word found.');
  else {
    const star = earned > before
      ? ['★ Red numbers unlocked', '★ White numbers unlocked', '★ Hints unlocked'][earned - 1] : '';
    const all = w.length === letters.length ? '🎉 All nine letters! ' : '';
    toast([(viaReveal ? '💡 ' : '') + `${all}${w} +${points(w)}`, star, extra].filter(Boolean).join(' · '));
  }
  render();
  if (done) showComplete();
}

// ----- reveals ---------------------------------------------------------------

// Like Squaredle: reveals only work on 4 to 6 letter words. A reveal picks a
// random missing word of one length, or once the hints are unlocked, the
// missing word you tap (twice, so a stray tap doesn't waste it). The word's
// letters then light up in order on the board, and it counts once you tap it out.
const REVEALABLE = (w) => w.length <= 6;
let armed = null, armedTimer;
const noReveals = () => say(state.starReveal ? 'No reveals left on this board' : 'No reveals left. Reach the third star for another.', 'neutral');
// Closes the word list so the glowing letters can be seen.
function toBoard(text) {
  $('words').close();
  $('board').scrollIntoView({ behavior: 'smooth', block: 'center' });
  say(text, 'neutral');
}
const tracingFirst = () => toBoard('💡 Tap out the glowing word on the board first');
function revealRandom(len) {
  if (state.guide) return tracingFirst();
  if (!state.reveals) return noReveals();
  const left = board.words.filter((w) => w.length === len && !state.found.includes(w));
  if (!left.length) return;
  useReveal(left[Math.floor(Math.random() * left.length)]);
}
function useReveal(w) {
  state.reveals--;
  state.guide = w;
  armed = null;
  save();
  render();
  startGuide();
  toBoard('💡 Tap the glowing letters in order');
}
// Lights up the revealed word's letters one by one, over and over, until it's found.
let guideTimer = null;
function startGuide() {
  clearInterval(guideTimer);
  guideTimer = null;
  tiles().forEach((t) => t.classList.remove('guide'));
  if (!state.guide) return;
  const steps = [...state.guide].map((ch) => letters.indexOf(ch));
  let k = 0;
  guideTimer = setInterval(() => {
    k = (k + 1) % (steps.length + 3);      // all lit, then a short pause before starting again
    tiles().forEach((t, i) => t.classList.toggle('guide', steps.slice(0, k).includes(i)));
  }, 450);
}
function tapMissing(w) {
  if (state.guide) return tracingFirst();
  if (!state.reveals) return noReveals();
  if (armed === w) { clearTimeout(armedTimer); return useReveal(w); }
  armed = w;
  clearTimeout(armedTimer);
  armedTimer = setTimeout(() => { armed = null; render(); }, 3000);
  say('Tap it again to use a reveal', 'neutral');
  render();
}

function starsEarned() {
  const got = state.found.reduce((t, w) => t + points(w), 0) / totalPoints;
  return STARS.filter((s) => got >= s).length;
}

// ----- rendering -------------------------------------------------------------

function clearPath() { path = []; typedMiss = ''; renderPath(); }

function renderPath() {
  tiles().forEach((t, i) => {
    const at = path.indexOf(i);
    t.classList.toggle('sel', at >= 0);
    t.dataset.step = at >= 0 ? at + 1 : '';
  });
  const cur = $('current');
  const word = wordOnBoard();
  const msg = !word && !typedMiss && message;
  cur.className = msg ? `msg ${msg.kind}` : '';
  cur.innerHTML = msg ? '' : word + (typedMiss ? `<span class="bad">${typedMiss}</span>` : '');
  if (msg) cur.textContent = msg.text;
  // Jump lines join the tapped letters in order.
  const wrap = $('board-wrap').getBoundingClientRect();
  const all = tiles();
  const pts = path.map((i) => {
    const r = all[i].getBoundingClientRect();
    return `${r.left + r.width / 2 - wrap.left},${r.top + r.height / 2 - wrap.top}`;
  });
  $('trail').innerHTML = pts.length > 1 ? `<polyline points="${pts.join(' ')}"/>` : '';
}

function render() {
  const stars = starsEarned();
  const got = state.found.reduce((t, w) => t + points(w), 0);
  $('progress').querySelector('.fill').style.width = `${(100 * got) / totalPoints}%`;
  $('progress').querySelectorAll('.star').forEach((s, i) => s.classList.toggle('on', i < stars));

  // Tile numbers count only words still to find; a tile fades when none are left.
  const left = board.words.filter((w) => !state.found.includes(w));
  tiles().forEach((t, i) => {
    const ch = letters[i];
    const starts = left.filter((w) => w[0] === ch).length;
    const uses = left.filter((w) => w.includes(ch)).length;
    t.querySelector('.start').textContent = stars >= 1 && starts ? starts : '';
    t.querySelector('.use').textContent = stars >= 2 && uses ? uses : '';
    t.classList.toggle('done', uses === 0);
  });

  $('count').querySelector('.words-count').innerHTML =
    `<b>${state.found.length}</b> / ${board.words.length} words` + (state.bonus.length ? ` <small>(+${state.bonus.length})</small>` : '');
  $('hints').hidden = stars < 3;
  $('hint-letters').checked = state.hintLetters;
  $('hint-sort').checked = state.hintSort;
  renderWords(stars >= 3);
  renderPath();
}

function renderWords(hintsOn) {
  const showLetters = hintsOn && state.hintLetters;
  const sortAll = hintsOn && state.hintSort;
  const byLen = {};
  for (const w of board.words) (byLen[w.length] ||= []).push(w);
  let html = `<h3>Words: ${state.found.length} of ${board.words.length}</h3>` +
    `<p class="reveals">💡 Reveals remaining: ${state.reveals}` +
    `${state.starReveal ? '' : ' <span class="note">(reach the third star for another)</span>'}</p>`;
  for (const len of Object.keys(byLen).sort((a, b) => a - b)) {
    const all = byLen[len];
    const found = all.filter((w) => state.found.includes(w));
    // Missing words appear as blanks; with the sort hint they sit in alphabetical order among the found ones.
    const items = sortAll ? all.slice().sort()
      : [...state.found.filter((w) => w.length == len), ...all.filter((w) => !found.includes(w)).sort()];
    html += `<div class="group-title">${len} letters · ${found.length} of ${all.length}</div><div class="words">` +
      items.map((w) => {
        const cls = state.revealed.includes(w) ? ' revealed' : '';
        if (found.includes(w)) return `<span class="word${cls}">${w}</span>`;
        if (!sortAll && !showLetters) return '';
        const shown = showLetters ? hinted(w) : '_'.repeat(w.length);
        return `<span class="word missing${armed === w ? ' armed' : ''}"${REVEALABLE(w) ? ` data-miss="${w}"` : ''}>${shown}</span>`;
      }).join('') + '</div>';
    // Until the missing words show as blanks, say how many are left, with a reveal link for short words.
    const left = all.length - found.length;
    if (left && !sortAll && !showLetters) {
      html += `<p class="left">+${left} word${left > 1 ? 's' : ''} left` +
        (len <= 6 && state.reveals ? ` · <button class="link" data-reveal="${len}">Reveal a random word</button>` : '') + '</p>';
    }
  }
  $('word-list').innerHTML = html;
  $('bonus-list').innerHTML = state.bonus.length
    ? `<h3>Bonus words: ${state.bonus.length}</h3><div class="words">${state.bonus.map((w) => `<span class="word">${w}</span>`).join('')}</div>`
    : '';
}

// ----- messages --------------------------------------------------------------

// Messages show on the line above the board, where the word being built goes.
let message = null, messageTimer;
// kind: 'good' (green), 'bad' (red, for words that don't count) or 'neutral'.
function say(text, kind) {
  message = { text, kind };
  // The word list covers the board, so it shows its own copy of the message.
  const wm = $('words-msg');
  wm.textContent = $('words').open ? text : '';
  wm.className = `msg ${kind}`;
  clearTimeout(messageTimer);
  messageTimer = setTimeout(() => { message = null; wm.textContent = ''; renderPath(); }, 2200);
  renderPath();
}
const toast = (text) => say(text, 'good');
const flash = (word, why) => say(`${word}: ${why.toLowerCase()}`, 'bad');

// ----- controls --------------------------------------------------------------

$('enter').onclick = submit;
$('delete').onclick = backspace;
// Where the letters sit doesn't matter, so shuffling them can shake loose new words.
$('shuffle').onclick = () => {
  const order = state.order.slice();
  do {
    for (let k = order.length - 1; k > 0; k--) {
      const j = Math.floor(Math.random() * (k + 1));
      [order[k], order[j]] = [order[j], order[k]];
    }
  } while (order.join() === state.order.join());
  state.order = order;
  save();
  buildBoard();
  startGuide();
  render();
};
// Taps in the word list: a missing word can be revealed.
$('word-list').addEventListener('click', (e) => {
  const el = e.target.closest('[data-miss], [data-reveal]');
  if (!el) return;
  if (el.dataset.reveal) revealRandom(+el.dataset.reveal);
  else tapMissing(el.dataset.miss);
});
$('hint-letters').onchange = (e) => { state.hintLetters = e.target.checked; save(); render(); };
$('hint-sort').onchange = (e) => { state.hintSort = e.target.checked; save(); render(); };
// Two taps to start over, so a stray tap can't wipe a board.
let resetArmed;
$('reset').onclick = () => {
  if (!resetArmed) {
    $('reset').textContent = 'Tap again to clear all found words';
    resetArmed = setTimeout(() => { resetArmed = null; $('reset').textContent = 'Start this board over'; }, 3000);
    return;
  }
  clearTimeout(resetArmed); resetArmed = null;
  $('reset').textContent = 'Start this board over';
  state = freshState();
  save(); buildBoard(); render(); startGuide();
};
$('back').onclick = showHome;
const wordsDialog = $('words');
// The list reopens where you left it on each board.
const listScroll = {};
const listBody = wordsDialog.querySelector('.sheet-body');
$('count').onclick = () => { wordsDialog.showModal(); listBody.scrollTop = listScroll[boardNo] || 0; };
// Saved as you scroll: by the time the dialog's close event fires, it has already lost its scroll position.
listBody.addEventListener('scroll', () => { if (wordsDialog.open) listScroll[boardNo] = listBody.scrollTop; });
wordsDialog.querySelector('.close').onclick = () => wordsDialog.close();
// Tapping outside the list closes it too.
wordsDialog.addEventListener('click', (e) => { if (e.target === wordsDialog) wordsDialog.close(); });

// ----- board complete --------------------------------------------------------

// The most recent unfinished board before this one, or failing that, after it.
function nextBoard() {
  const today = todayNo();
  for (let n = boardNo - 1; n >= 0; n--) if (!isComplete(n)) return n;
  for (let n = boardNo + 1; n <= today; n++) if (!isComplete(n)) return n;
  return null;
}
const complete = $('complete');
function showComplete() {
  const next = nextBoard();
  complete.querySelector('.summary').textContent = next !== null
    ? `You found all ${board.words.length} words. Ready for another?`
    : `You found all ${board.words.length} words, and every Jumple so far is done! Come back tomorrow for a new one.`;
  const go = complete.querySelector('.go');
  go.hidden = next === null;
  if (next !== null) {
    go.textContent = `Play ${boardLabel(next)} ›`;
    go.onclick = () => { complete.close(); openBoard(next); };
  }
  complete.showModal();
  (next !== null ? go : complete.querySelector('.home')).focus();
}
complete.querySelector('.home').onclick = () => { complete.close(); showHome(); };
complete.querySelector('.stay').onclick = () => complete.close();

// How to play: a few short screens with Back / Next / Let's play.
const rules = $('rules');
const steps = [...rules.querySelectorAll('.step')];
let step = 0;
function showStep(n) {
  step = n;
  steps.forEach((el, i) => { el.hidden = i !== n; });
  rules.querySelector('.back').disabled = n === 0;
  rules.querySelector('.next').textContent = n === steps.length - 1 ? "Let's play" : 'Next';
  rules.querySelector('.dots').innerHTML = steps.map((_, i) => `<i class="${i === n ? 'on' : ''}"></i>`).join('');
}
function openRules() {
  showStep(0);
  rules.showModal();
  rules.scrollTop = 0;
  rules.querySelector('.next').focus();
}
rules.querySelector('.back').onclick = () => showStep(step - 1);
rules.querySelector('.next').onclick = () => (step < steps.length - 1 ? showStep(step + 1) : rules.close());
rules.querySelector('.close').onclick = () => rules.close();
$('help').onclick = openRules;
window.addEventListener('resize', renderPath);

showHome();
if (!store.get('jumple:seen-rules')) { store.set('jumple:seen-rules', true); openRules(); }
